# SPDX-License-Identifier: Apache-2.0
import statistics
import time
import torch
from tools.qwen4exp.direct_hc_residual import DirectHCResidual
from tools.qwen4exp.resident_worker import QwenResidentExtension

def prepare():
    path = '/srv/ai/src/qwen-shroud-resume-20261010/residual-v3.bin'
    kernel = torch.classes.qwen_native_hc_residual_v3.Kernel(path, 'qwen_hc_residual_v3')
    return DirectHCResidual(path, kernel=kernel, launch=torch.ops.qwen_native_hc_residual_v3.launch)

def validate(op):
    cases = 0
    with torch.inference_mode():
        for rows,width in ((1,512),(3,2560),(18,2560),(128,2560),(640,2560),(2560,2560),(7,3072)):
            gen=torch.Generator().manual_seed(rows+width)
            for dtype in (torch.float16,torch.float32):
                h=torch.randn(rows,4*width,generator=gen).half().npu()
                b=torch.randn(rows,width,generator=gen).half().npu()
                c=(torch.rand(rows,4,generator=gen)*2).to(dtype).npu()
                for pattern in ('random','zero','large','subnormal','signed_zero'):
                    if pattern=='zero': h.zero_(); b.zero_(); c.fill_(1)
                    elif pattern=='large': h.fill_(60000); b.fill_(60000); c.fill_(2); h[:,::2].neg_(); b[:,::2].neg_()
                    elif pattern=='subnormal': h.fill_(2**-24); b.fill_(-2**-24); c.fill_(0.5)
                    elif pattern=='signed_zero': h.fill_(-0.0); b.fill_(-0.0); c.zero_(); c[:,::2].fill_(-0.0)
                    expected=(h.float().view(rows,4,width)+b.float()[:,None]*c.float()[:,:,None]).flatten(1).half()
                    actual=op(h,b,c)
                    assert torch.equal(expected.cpu().view(torch.uint8),actual.cpu().view(torch.uint8)),(rows,width,str(dtype),pattern)
                    cases+=1
    return {'passed':True,'cases':cases,'exact_bytes':True}
